function hdpQuestion(question,card){if(String(question).startsWith('Hablame sobre: '))return question;if(card?.visual)return 'Hablame sobre: '+question+' Desarrollá cada identificación y función solicitada en la lámina.';return 'Hablame sobre: '+String(question||'el tema de examen').replace(/^[¿¡\s]+|[?.\s]+$/g,'').trim()+'. Desarrollá una explicación técnica completa: principio de funcionamiento o fundamento físico, componentes o elementos que intervienen y su función, conexiones o relaciones técnicas, recorrido del fluido o transformación de energía, relación con el sistema y condiciones relevantes. En temas conceptuales, explicá las variables y la evolución del proceso. Incluí mantenimiento o fallas sólo cuando correspondan.'}
module.exports={hdpQuestion};
